	var x = parseInt(arr[1]);
if(x == "")
	 tw.local.newRequestId = tw.local.parentRequestNumber+"-01";
else
{	 
	x= x+1;
	
	if(x < 9)
	tw.local.tmpvar = "0"+ x;
	else
	tw.local.tmpvar = x;
	
	
	tw.local.newRequestId = tw.local.parentRequestNumber+'-'+tw.local.tmpvar;
	
}

tw.local.sql = "select requestNo from "+ tw.env.LKP_DB_Schema +".ODC_RequestInfo where PARENTREQUESTNO = ? order by requestNo desc;"

